  //#define MEASURE_HEURISTICS // Define only if heuristics should be calculated for parameter selection

  #ifndef RRLWR_SECURITY_LEVEL
    #define RRLWR_SECURITY_LEVEL 512
  #elif (RRLWR_SECURITY_LEVEL != 512)
    #error "Octarine-512 only supports RRLWR_SECURITY_LEVEL=512"
  #endif

  // Algorithm parameters (should not be changed)
  #if (RRLWR_SECURITY_LEVEL == 128)
    #define RRLWR_N                    (1024)
    #define RRLWR_K                    (1)
    #define RRLWR_SIGN_LOGQ            (24)
    #define RRLWR_SIGN_LOGP            (21)
    #define RRLWR_SIGN_LOG_ETA         (2)
    #define RRLWR_SIGN_D               (11)
    #define RRLWR_SIGN_TAU             (16)
    #define RRLWR_SIGN_LAMBDA          (128)
    #define RRLWR_SIGN_LOG_GAMMA1      (18)
    #define RRLWR_SIGN_LOG_GAMMA2      (17)
    #define RRLWR_SIGN_OMEGA           (79)
  #elif (RRLWR_SECURITY_LEVEL == 256)
    #define RRLWR_N                    (1024)
    #define RRLWR_K                    (2)
    #define RRLWR_SIGN_LOGQ            (24)
    #define RRLWR_SIGN_LOGP            (22)
    #define RRLWR_SIGN_LOG_ETA         (1)
    #define RRLWR_SIGN_D               (13)
    #define RRLWR_SIGN_TAU             (36)
    #define RRLWR_SIGN_LAMBDA          (256)
    #define RRLWR_SIGN_LOG_GAMMA1      (19)
    #define RRLWR_SIGN_LOG_GAMMA2      (18)
    #define RRLWR_SIGN_OMEGA           (210)
  #elif (RRLWR_SECURITY_LEVEL == 512)
    #define RRLWR_N                    (1024)
    #define RRLWR_K                    (5)
    #define RRLWR_SIGN_LOGQ            (24)
    #define RRLWR_SIGN_LOGP            (22)
    #define RRLWR_SIGN_LOG_ETA         (1)
    #define RRLWR_SIGN_D               (14)
    #define RRLWR_SIGN_TAU             (87)
    #define RRLWR_SIGN_LAMBDA          (512)
    #define RRLWR_SIGN_LOG_GAMMA1      (21)
    #define RRLWR_SIGN_LOG_GAMMA2      (20)
    #define RRLWR_SIGN_OMEGA           (399)
  #endif

  #if ((RRLWR_SIGN_LOG_ETA+1) != (RRLWR_SIGN_LOGQ-RRLWR_SIGN_LOGP))
    #error "Size of s2 should match s1"
  #endif

  #if (((RRLWR_SIGN_OMEGA + RRLWR_K) % 4) != 0)
    #error "Omega+k should be 0 mod 4 to pack efficiently"
  #endif

  #define RRLWR_SIGN_Q                 ((int32_t)1 << RRLWR_SIGN_LOGQ)
  #define RRLWR_SIGN_P                 ((int32_t)1 << RRLWR_SIGN_LOGP)
  #define RRLWR_SIGN_ETA               ((int32_t)1 << RRLWR_SIGN_LOG_ETA)
  #define RRLWR_SIGN_GAMMA1            ((int32_t)1 << RRLWR_SIGN_LOG_GAMMA1)
  #define RRLWR_SIGN_GAMMA2            ((int32_t)1 << RRLWR_SIGN_LOG_GAMMA2)
  #define RRLWR_SIGN_BETA              (RRLWR_SIGN_TAU * RRLWR_SIGN_ETA)

  #define RRLWR_SIGN_XI_LEN            (64)
  #define RRLWR_SIGN_RHO_LEN           (64)
  #define RRLWR_SIGN_SEED_A_LEN        (RRLWR_SIGN_RHO_LEN)
  #define RRLWR_SIGN_RHOPRIME_LEN      (128)
  #define RRLWR_SIGN_RHOPRIMEPRIME_LEN (128)
  #define RRLWR_SEED_S_LEN             (RRLWR_SIGN_RHOPRIME_LEN)
  #define RRLWR_SIGN_K_LEN             (64)
  #define RRLWR_SIGN_TR_LEN            (128)
  #define RRLWR_SIGN_MU_LEN            (128)
  #define RRLWR_SIGN_RND_LEN           (64)
  #define RRLWR_SIGN_CTILDE_LEN        (RRLWR_SIGN_LAMBDA/4)
  #define RRLWR_SIGN_MAX_TAU_BYTES     (11) // tau = 87 is maximum number of bits
  #define RRLWR_SIGN_SAMPLE_C_LEN      (80)
  #define RRLWR_SIGN_SAMPLE_C_NUM_INDICES (8*RRLWR_SIGN_SAMPLE_C_LEN/10)

  #if (!((8*RRLWR_SIGN_MAX_TAU_BYTES) > RRLWR_SIGN_TAU))
    #error "Not enough sign bits sampled for SampleInBall"
  #endif

  #if (((RRLWR_SIGN_SAMPLE_C_LEN) % 10) != 0)
    #error "Must sample a multiple of 10 bits at a time to efficiently unpack the sampled byte sequence"
  #endif

  #define RRLWR_PACKED_POLY2_LEN       (2*RRLWR_N/8)
  #define RRLWR_PACKED_POLY11_LEN      (11*RRLWR_N/8)
  #define RRLWR_SIGN_PACKED_POLYB0_LEN (RRLWR_SIGN_D*RRLWR_N/8)
  #define RRLWR_SIGN_PACKED_POLYB1_LEN ((RRLWR_SIGN_LOGP-RRLWR_SIGN_D)*RRLWR_N/8)
  #define RRLWR_SIGN_PACKED_POLYQ_LEN  (RRLWR_SIGN_LOGQ*RRLWR_N/8)
  #define RRLWR_SIGN_PACKED_POLY_GAMMA1_LEN ((RRLWR_SIGN_LOG_GAMMA1+1)*RRLWR_N/8)
  #define RRLWR_SIGN_PACKED_POLYW1_LEN (RRLWR_N*(RRLWR_SIGN_LOGQ-RRLWR_SIGN_LOG_GAMMA2-1)/8)
  #define RRLWR_SIGN_PACKED_W1_LEN     (RRLWR_K*RRLWR_SIGN_PACKED_POLYW1_LEN)
  #define RRLWR_SIGN_PACKED_Z_LEN      (RRLWR_K*RRLWR_SIGN_PACKED_POLY_GAMMA1_LEN)

  #define RRLWR_SIGN_S_LEN             (RRLWR_K*RRLWR_N*(RRLWR_SIGN_LOG_ETA+1)/8)
  #define RRLWR_SIGN_H_LEN16           (RRLWR_SIGN_OMEGA + RRLWR_K) // Length as 16-bit indices
  #define RRLWR_SIGN_H_LEN8            (10*(RRLWR_SIGN_OMEGA + RRLWR_K)/8) // Length as byte array
  #define RRLWR_SIGN_B0_LEN            (RRLWR_K*RRLWR_SIGN_PACKED_POLYB0_LEN)
  #define RRLWR_SIGN_B1_LEN            (RRLWR_K*RRLWR_SIGN_PACKED_POLYB1_LEN)
  #define RRLWR_SIGN_SK_LEN            (RRLWR_SIGN_RHO_LEN + RRLWR_SIGN_K_LEN + RRLWR_SIGN_TR_LEN + 2*RRLWR_SIGN_S_LEN + RRLWR_SIGN_B0_LEN)
  #define RRLWR_SIGN_PK_LEN            (RRLWR_SIGN_RHO_LEN + RRLWR_SIGN_B1_LEN)
  #define RRLWR_SIGN_SIG_LEN           (RRLWR_SIGN_CTILDE_LEN + RRLWR_SIGN_PACKED_Z_LEN + RRLWR_SIGN_H_LEN8)

  #define GENERATE_RANDOM_BYTES(output, output_len, ctx) \
          get_random_number(ctx, output, 8*(output_len))

  // Keep the byte-length interface used by the RRLWR code while calling the SM3 pseudoXOF bit-length API.
  #define RRLWR_SM3_XOF(output, output_len, input, input_len) \
          pseudoXOF(8ULL*(unsigned long long)(output_len), (const unsigned char *)(input), 8ULL*(unsigned long long)(input_len), (unsigned char *)(output))

  #define RRLWR_XOF_SECRET(output, output_len, input, input_len) \
          RRLWR_SM3_XOF((output), (output_len), (input), (input_len))
  #define RRLWR_XOF_PUBLIC(output, output_len, input, input_len) \
          RRLWR_SM3_XOF((output), (output_len), (input), (input_len))
  #define RRLWR_SIGN_HASH_H(output, output_len, input, input_len) \
          RRLWR_SM3_XOF((output), (output_len), (input), (input_len))
  #define RRLWR_SIGN_HASH_SAMPLE_C(output, output_len, input, input_len) \
          RRLWR_SM3_XOF((output), (output_len), (input), (input_len))

